import hashlib

import pytest

from itsdangerous.serializer import Serializer
from itsdangerous.signer import Signer


CONFIGURED_SALT = "configured-salt"


def make_serializer(**kwargs):
    return Serializer(secret_key="secret-key", salt=CONFIGURED_SALT, **kwargs)


def test_none_selects_configured_salt():
    serializer = make_serializer()
    signers = list(serializer.iter_unsigners(None))
    assert len(signers) == 1
    assert signers[0].salt == CONFIGURED_SALT


def test_default_argument_selects_configured_salt():
    serializer = make_serializer()
    signers = list(serializer.iter_unsigners())
    assert len(signers) == 1
    assert signers[0].salt == CONFIGURED_SALT


@pytest.mark.parametrize("empty_salt", ["", b""])
def test_explicit_empty_salt_overrides_configured_salt(empty_salt):
    serializer = make_serializer()
    signers = list(serializer.iter_unsigners(empty_salt))
    assert len(signers) == 1
    assert signers[0].salt == empty_salt
    assert signers[0].salt != CONFIGURED_SALT


@pytest.mark.parametrize("empty_salt", ["", b""])
def test_explicit_empty_salt_applies_to_fallback_signers(empty_salt):
    serializer = make_serializer(
        fallback_signers=[{"digest_method": hashlib.sha256}]
    )
    signers = list(serializer.iter_unsigners(empty_salt))
    assert len(signers) == 2
    for signer in signers:
        assert signer.salt == empty_salt
        assert signer.salt != CONFIGURED_SALT


def test_non_empty_explicit_salt_is_used():
    serializer = make_serializer()
    signers = list(serializer.iter_unsigners("explicit-salt"))
    assert len(signers) == 1
    assert signers[0].salt == "explicit-salt"


def test_fallback_signers_use_configured_salt_when_none():
    serializer = make_serializer(
        fallback_signers=[
            {"digest_method": hashlib.sha256},
            (Signer, {"digest_method": hashlib.sha256}),
        ]
    )
    signers = list(serializer.iter_unsigners(None))
    assert len(signers) == 3
    for signer in signers:
        assert signer.salt == CONFIGURED_SALT

from __future__ import annotations

import pytest

from markupsafe import Markup


class HasHTML:
    def __init__(self, html: str) -> None:
        self._html = html

    def __html__(self) -> str:
        return self._html


def test_add_str_escapes() -> None:
    result = Markup("<b>") + "<i>"
    assert result == Markup("<b>&lt;i&gt;")
    assert type(result) is Markup


def test_add_empty_str() -> None:
    result = Markup("abc") + ""
    assert result == Markup("abc")
    assert type(result) is Markup


def test_add_markup_not_double_escaped() -> None:
    result = Markup("<b>") + Markup("<i>")
    assert result == Markup("<b><i>")


def test_add_has_html() -> None:
    result = Markup("<b>") + HasHTML("<i>")
    assert result == Markup("<b><i>")
    assert type(result) is Markup


def test_add_int_raises_type_error() -> None:
    with pytest.raises(TypeError):
        Markup("foo") + 1


def test_add_zero_raises_type_error() -> None:
    with pytest.raises(TypeError):
        Markup("foo") + 0


def test_add_none_raises_type_error() -> None:
    with pytest.raises(TypeError):
        Markup("foo") + None


def test_add_list_raises_type_error() -> None:
    with pytest.raises(TypeError):
        Markup("foo") + ["bar"]


def test_add_float_raises_type_error() -> None:
    with pytest.raises(TypeError):
        Markup("foo") + 1.5


def test_add_preserves_subclass() -> None:
    class Sub(Markup):
        pass

    result = Sub("a") + "b"
    assert type(result) is Sub
    assert result == Markup("ab")

