from __future__ import annotations

import pytest

from markupsafe import Markup


def test_split_default_splits_all() -> None:
    assert Markup("a b c").split() == [Markup("a"), Markup("b"), Markup("c")]


def test_split_maxsplit_zero_leaves_unsplit() -> None:
    # str semantics: maxsplit=0 means no splitting occurs.
    result = Markup("a b c").split(maxsplit=0)
    assert result == [Markup("a b c")]
    assert len(result) == 1


def test_split_maxsplit_zero_with_sep_leaves_unsplit() -> None:
    result = Markup("a,b,c").split(",", 0)
    assert result == [Markup("a,b,c")]


def test_split_maxsplit_one() -> None:
    assert Markup("a b c").split(maxsplit=1) == [Markup("a"), Markup("b c")]


def test_split_maxsplit_one_with_sep() -> None:
    assert Markup("a,b,c").split(",", 1) == [Markup("a"), Markup("b,c")]


def test_split_negative_maxsplit_splits_all() -> None:
    assert Markup("a b c").split(maxsplit=-1) == [
        Markup("a"),
        Markup("b"),
        Markup("c"),
    ]


def test_split_results_are_markup() -> None:
    result = Markup("a b").split(maxsplit=0)
    assert all(isinstance(part, Markup) for part in result)


def test_split_empty_string_maxsplit_zero() -> None:
    assert Markup("").split(maxsplit=0) == [Markup("")]

import pytest

from itsdangerous.signer import Signer


@pytest.fixture
def signer():
    return Signer("secret-key")


def test_valid_signature_accepted(signer):
    signed = signer.sign("value")
    sig = signed.rsplit(b".", 1)[1]
    assert signer.verify_signature(b"value", sig) is True


def test_malformed_base64_signature_rejected(signer):
    # "!!!" is not valid base64; must not be accepted as a valid signature.
    assert signer.verify_signature(b"value", b"!!!") is False


def test_non_base64_bytes_rejected(signer):
    # Arbitrary non-base64 bytes must be rejected.
    assert signer.verify_signature(b"value", b"\xff\xfe\x00") is False


def test_bad_padding_rejected(signer):
    # A single base64 character cannot form a valid signature; reject.
    assert signer.verify_signature(b"value", b"A") is False


def test_wrong_but_wellformed_signature_rejected(signer):
    # Well-formed base64 that does not match the value must be rejected.
    assert signer.verify_signature(b"value", b"YWJjZA==") is False

import hashlib
import hmac

import pytest

from itsdangerous.signer import HMACAlgorithm


KEYS = [b"", b"secret-key", b"\x00", b"a" * 64]
DIGESTS = [hashlib.sha1, hashlib.sha256, hashlib.sha512]


@pytest.mark.parametrize("digest", DIGESTS)
@pytest.mark.parametrize("key", KEYS)
def test_empty_message_matches_standard_hmac(key, digest):
    alg = HMACAlgorithm(digest)
    expected = hmac.new(key, msg=b"", digestmod=digest).digest()
    assert alg.get_signature(key, b"") == expected


@pytest.mark.parametrize("digest", DIGESTS)
@pytest.mark.parametrize("key", KEYS)
def test_empty_message_not_zero_byte_substitution(key, digest):
    alg = HMACAlgorithm(digest)
    zero_byte = hmac.new(key, msg=b"\x00", digestmod=digest).digest()
    assert alg.get_signature(key, b"") != zero_byte


@pytest.mark.parametrize("digest", DIGESTS)
def test_non_empty_message_matches_standard_hmac(digest):
    alg = HMACAlgorithm(digest)
    key = b"secret-key"
    value = b"payload"
    expected = hmac.new(key, msg=value, digestmod=digest).digest()
    assert alg.get_signature(key, value) == expected


def test_empty_message_digest_length():
    alg = HMACAlgorithm(hashlib.sha256)
    assert len(alg.get_signature(b"key", b"")) == hashlib.sha256().digest_size

