from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _FixedTz(tzinfo):
    def __init__(self, offset_hours):
        self._offset = timedelta(hours=offset_hours)

    def utcoffset(self, dt):
        return self._offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "fixed%+d" % self._offset.total_seconds()


class _Receiver(_FixedTz):
    def __init__(self):
        super(_Receiver, self).__init__(1)
        self.calls = []

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        self.calls.append(dt)
        return dt + self._offset


def test_mismatched_tzinfo_raises_value_error_and_skips_conversion():
    receiver = _Receiver()
    other = _FixedTz(2)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=other)

    with pytest.raises(ValueError):
        receiver.fromutc(dt)

    assert receiver.calls == []


def test_none_tzinfo_raises_value_error_and_skips_conversion():
    receiver = _Receiver()
    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        receiver.fromutc(dt)

    assert receiver.calls == []


def test_matching_tzinfo_calls_wrapped_conversion_once():
    receiver = _Receiver()
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=receiver)

    result = receiver.fromutc(dt)

    assert receiver.calls == [dt]
    assert result == datetime(2020, 1, 1, 13, 0, tzinfo=receiver)


def test_non_datetime_raises_type_error():
    receiver = _Receiver()

    with pytest.raises(TypeError):
        receiver.fromutc("2020-01-01T12:00:00")

    assert receiver.calls == []

from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _FixedOffset(tzinfo):
    def __init__(self, offset_hours):
        self._offset = timedelta(hours=offset_hours)

    def utcoffset(self, dt):
        return self._offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "fixed%+d" % self._offset.total_seconds()


class _Receiver(tzinfo):
    """A tzinfo used as the receiving timezone (self) in fromutc."""

    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "receiver"


class _Sentinel:
    def __init__(self):
        self.calls = []

    def __call__(self, self_tz, dt):
        self.calls.append((self_tz, dt))
        return "converted"


def _make_wrapped():
    sentinel = _Sentinel()

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        return sentinel(self, dt)

    return fromutc, sentinel


def test_fromutc_rejects_foreign_tzinfo_with_value_error():
    fromutc, sentinel = _make_wrapped()
    receiver = _Receiver()
    foreign = _FixedOffset(2)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=foreign)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert sentinel.calls == []


def test_fromutc_rejects_naive_datetime_with_value_error():
    fromutc, sentinel = _make_wrapped()
    receiver = _Receiver()
    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert sentinel.calls == []


def test_fromutc_accepts_matching_tzinfo_and_delegates():
    fromutc, sentinel = _make_wrapped()
    receiver = _Receiver()
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=receiver)

    result = fromutc(receiver, dt)

    assert result == "converted"
    assert sentinel.calls == [(receiver, dt)]


def test_fromutc_rejects_non_datetime_with_type_error():
    fromutc, sentinel = _make_wrapped()
    receiver = _Receiver()

    with pytest.raises(TypeError):
        fromutc(receiver, "2020-01-01T12:00:00")

    assert sentinel.calls == []

from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _SentinelTZ(tzinfo):
    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "sentinel"


class _Recorder:
    def __init__(self):
        self.calls = []

    def __call__(self, self_tz, dt):
        self.calls.append((self_tz, dt))
        return "converted"


def _make_validated(recorder):
    @_validate_fromutc_inputs
    def fromutc(self, dt):
        return recorder(self, dt)

    return fromutc


def test_fromutc_rejects_foreign_tzinfo_with_valueerror():
    tz_self = _SentinelTZ()
    tz_other = _SentinelTZ()
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    dt = datetime(2020, 1, 1, 12, 0, tzinfo=tz_other)

    with pytest.raises(ValueError):
        fromutc(tz_self, dt)

    assert recorder.calls == []


def test_fromutc_rejects_naive_datetime_with_valueerror():
    tz_self = _SentinelTZ()
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        fromutc(tz_self, dt)

    assert recorder.calls == []


def test_fromutc_rejects_non_datetime_with_typeerror():
    tz_self = _SentinelTZ()
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    with pytest.raises(TypeError):
        fromutc(tz_self, "2020-01-01T12:00:00")

    assert recorder.calls == []


def test_fromutc_delegates_when_tzinfo_is_self():
    tz_self = _SentinelTZ()
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    dt = datetime(2020, 1, 1, 12, 0, tzinfo=tz_self)

    result = fromutc(tz_self, dt)

    assert result == "converted"
    assert recorder.calls == [(tz_self, dt)]

