import pytest

from itsdangerous.signer import Signer


def make_signer(**kwargs):
    return Signer(secret_key="default-secret", salt="my-salt", **kwargs)


def test_derive_key_none_returns_last_secret_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key() == b"default-secret"
    assert signer.derive_key(None) == b"default-secret"


def test_derive_key_none_returns_explicit_bytes_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"explicit") == b"explicit"


def test_derive_key_none_returns_explicit_str_key_as_bytes():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key("explicit") == b"explicit"


def test_derive_key_none_empty_bytes_is_distinct_from_none():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"") == b""
    assert signer.derive_key(b"") != signer.derive_key(None)


def test_derive_key_none_empty_str_is_distinct_from_none():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key("") == b""
    assert signer.derive_key("") != signer.derive_key(None)


def test_derive_key_invalid_method_raises_type_error():
    signer = make_signer(key_derivation="invalid")
    with pytest.raises(TypeError):
        signer.derive_key()

