def test_none_derivation_none_key_uses_last_secret_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(None) == b"default-secret"


def test_none_derivation_returns_explicit_nonempty_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"explicit") == b"explicit"


def test_none_derivation_returns_explicit_str_key_as_bytes():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key("explicit") == b"explicit"


def test_empty_bytes_key_distinct_from_omitted_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"") != signer.derive_key()


def test_invalid_key_derivation_raises_type_error():
    signer = make_signer(key_derivation="invalid")
    with pytest.raises(TypeError):
        signer.derive_key()

import pytest

from itsdangerous.signer import Signer


def make_signer(key_derivation="none", secret_keys=None):
    if secret_keys is None:
        secret_keys = ["default-secret"]
    return Signer(
        secret_key=secret_keys,
        salt=b"itsdangerous",
        key_derivation=key_derivation,
    )


def test_none_derivation_explicit_empty_bytes_returns_empty_bytes():
    # Requirement: an explicitly supplied empty bytes key is distinct from an
    # omitted None key; with 'none' derivation the explicit key is returned.
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"") == b""


def test_none_derivation_omitted_key_uses_last_secret_key():
    signer = make_signer(key_derivation="none", secret_keys=["first", "last"])
    assert signer.derive_key() == b"last"


def test_none_derivation_none_key_uses_last_secret_key():
    signer = make_signer(key_derivation="none", secret_keys=["first", "last"])
    assert signer.derive_key(None) == b"last"


def test_empty_bytes_key_distinct_from_omitted_key():
    signer = make_signer(key_derivation="none", secret_keys=["default-secret"])
