import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _FixedOffset(tzinfo):
    def __init__(self, offset_minutes):
        self._offset = timedelta(minutes=offset_minutes)

    def utcoffset(self, dt):
        return self._offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "fixed"


class _Receiver(tzinfo):
    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "receiver"


class _Sentinel(object):
    def __init__(self):
        self.calls = []

    def __call__(self, self_, dt):
        self.calls.append((self_, dt))
        return "converted"


def _make_validated(sentinel):
    return _validate_fromutc_inputs(sentinel)


def test_fromutc_rejects_foreign_tzinfo_with_value_error():
    receiver = _Receiver()
    sentinel = _Sentinel()
    fromutc = _make_validated(sentinel)
    foreign = _FixedOffset(60)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=foreign)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert sentinel.calls == []


def test_fromutc_rejects_naive_datetime_with_value_error():
    receiver = _Receiver()
    sentinel = _Sentinel()
    fromutc = _make_validated(sentinel)
    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert sentinel.calls == []


def test_fromutc_rejects_other_receiver_instance_with_value_error():
    receiver = _Receiver()
    other_receiver = _Receiver()
    sentinel = _Sentinel()
    fromutc = _make_validated(sentinel)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=other_receiver)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert sentinel.calls == []


def test_fromutc_accepts_matching_tzinfo_and_calls_wrapped():
    receiver = _Receiver()
    sentinel = _Sentinel()
    fromutc = _make_validated(sentinel)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=receiver)

    result = fromutc(receiver, dt)

    assert result == "converted"
    assert sentinel.calls == [(receiver, dt)]


def test_fromutc_rejects_non_datetime_with_type_error():
    receiver = _Receiver()
    sentinel = _Sentinel()
    fromutc = _make_validated(sentinel)

    with pytest.raises(TypeError):
