from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _FixedTz(tzinfo):
    def __init__(self, offset_hours):
        self._offset = timedelta(hours=offset_hours)

    def utcoffset(self, dt):
        return self._offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "Fixed%+d" % (self._offset.total_seconds() // 3600)


class _Recorder:
    def __init__(self):
        self.calls = []

    def __call__(self, self_tz, dt):
        self.calls.append((self_tz, dt))
        return "converted"


def _make_validated(recorder):
    @_validate_fromutc_inputs
    def fromutc(self, dt):
        return recorder(self, dt)

    return fromutc


def test_mismatched_tzinfo_raises_value_error_and_skips_conversion():
    tz_a = _FixedTz(1)
    tz_b = _FixedTz(2)
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    dt = datetime(2020, 1, 1, 12, 0, tzinfo=tz_b)

    with pytest.raises(ValueError):
        fromutc(tz_a, dt)

    assert recorder.calls == []


def test_naive_datetime_raises_value_error_and_skips_conversion():
    tz_a = _FixedTz(1)
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        fromutc(tz_a, dt)

    assert recorder.calls == []


def test_matching_tzinfo_passes_through_and_calls_conversion_once():
    tz_a = _FixedTz(1)
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    dt = datetime(2020, 1, 1, 12, 0, tzinfo=tz_a)

    result = fromutc(tz_a, dt)

    assert result == "converted"
    assert len(recorder.calls) == 1
    called_self, called_dt = recorder.calls[0]
    assert called_self is tz_a
    assert called_dt is dt


def test_non_datetime_input_raises_type_error_and_skips_conversion():
    tz_a = _FixedTz(1)
    recorder = _Recorder()
    fromutc = _make_validated(recorder)

    with pytest.raises(TypeError):
        fromutc(tz_a, "2020-01-01T12:00:00")

    assert recorder.calls == []

