def test_split_maxsplit_zero_leaves_unsplit() -> None:
    # Requirement: maxsplit=0 leaves the string unsplit.
    result = Markup("a b c").split(maxsplit=0)
    assert result == [Markup("a b c")]
    assert len(result) == 1


def test_split_maxsplit_zero_with_sep() -> None:
    result = Markup("a,b,c").split(",", 0)
    assert result == [Markup("a,b,c")]


def test_split_maxsplit_zero_none_sep() -> None:
