import pytest

from itsdangerous.signer import Signer


@pytest.fixture
def signer():
    return Signer("secret-key")


def _valid_sig(signer, value=b"payload"):
    signed = signer.sign(value)
    return signed.rsplit(b".", 1)[1]


def test_valid_signature_accepted(signer):
    sig = _valid_sig(signer)
    assert signer.verify_signature(b"payload", sig) is True


def test_malformed_base64_invalid_chars_rejected(signer):
    # "!" is not in the base64 alphabet, so decoding fails.
    assert signer.verify_signature(b"payload", b"!!!!") is False


def test_malformed_base64_bad_padding_rejected(signer):
    # A single base64 character cannot form a valid block.
    assert signer.verify_signature(b"payload", b"A") is False


def test_malformed_base64_non_ascii_rejected(signer):
    # Non-ASCII bytes are not valid base64.
    assert signer.verify_signature(b"payload", b"\xff\xfe\xfd") is False


def test_malformed_base64_str_rejected(signer):
    # Invalid characters in a str signature must also be rejected.
    assert signer.verify_signature(b"payload", "not base64 @@@") is False


def test_wellformed_but_wrong_signature_rejected(signer):
    # A decodable but incorrect signature must not verify.
    assert signer.verify_signature(b"payload", b"AAAAAAAAAAAAAAAAAAAAAA==") is False

