from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _FixedOffset(tzinfo):
    def __init__(self, offset_minutes):
        self._offset = timedelta(minutes=offset_minutes)

    def utcoffset(self, dt):
        return self._offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "fixed"


class _Recorder(object):
    def __init__(self):
        self.calls = []

    def __call__(self, self_obj, dt):
        self.calls.append((self_obj, dt))
        return "converted"


def _make_decorated():
    recorder = _Recorder()

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        return recorder(self, dt)

    return fromutc, recorder


def test_mismatched_tzinfo_raises_value_error_and_skips_conversion():
    fromutc, recorder = _make_decorated()
    receiver = _FixedOffset(60)
    other = _FixedOffset(120)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=other)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert recorder.calls == []


def test_naive_datetime_raises_value_error_and_skips_conversion():
    fromutc, recorder = _make_decorated()
    receiver = _FixedOffset(0)
    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        fromutc(receiver, dt)

    assert recorder.calls == []


def test_non_datetime_raises_type_error_and_skips_conversion():
    fromutc, recorder = _make_decorated()
    receiver = _FixedOffset(0)

    with pytest.raises(TypeError):
        fromutc(receiver, "2020-01-01T12:00:00")

    assert recorder.calls == []


def test_matching_tzinfo_calls_wrapped_conversion():
    fromutc, recorder = _make_decorated()
    receiver = _FixedOffset(30)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=receiver)

    result = fromutc(receiver, dt)

    assert result == "converted"
    assert recorder.calls == [(receiver, dt)]

